# Lições de aprofundamento (10–22): mais profissões e a realidade do trabalho nos Países Baixos.

L(10, "Profissões técnicas", "Elektricien, monteur, timmerman: wie doet wat?",
  ["Nomear profissões técnicas e descrever o que fazem"],
  vocab=[V("v-elektricien","elektricien","eletricista","noun","de"), V("v-monteur","monteur","mecânico|técnico de montagem","noun","de"),
         V("v-timmerman","timmerman","carpinteiro","noun","de"), V("v-gereedschap","gereedschap","ferramentas","noun","het")],
  ex=[("De elektricien legt nieuwe leidingen aan.","O eletricista instala cabos novos."),("De monteur repareert de auto.","O mecânico repara o carro."),("De timmerman maakt een kast op maat.","O carpinteiro faz um armário à medida."),("Waar ligt mijn gereedschap?","Onde estão as minhas ferramentas?")],
  review=["v-repareren","v-beroep","v-loodgieter"],
  cefr=C, exs=[
    MA([("elektricien","eletricista"),("monteur","mecânico"),("timmerman","carpinteiro"),("loodgieter","canalizador")], "Profissões técnicas.", ["v-elektricien","v-monteur","v-timmerman","v-loodgieter"]),
    AR("gereedschap","as ferramentas","het", "Het gereedschap (coletivo, singular).", ["v-gereedschap"]),
    MC("Quem chama se faltar a luz na cozinha?", ["*de elektricien","de timmerman|Trabalha com madeira.","de kapper|Corta cabelo."], "Eletricidade → elektricien.", ["v-elektricien"]),
    MC("Quem repara uma fuga de água?", ["*de loodgieter","de monteur|Repara carros e máquinas.","de elektricien|Eletricidade."], "Água/canos → loodgieter.", ["v-loodgieter"]),
    TR("pt-nl","O mecânico repara o carro.", ["De monteur repareert de auto"], "repareren.", ["v-monteur","v-repareren"]),
    TR("nl-pt","De timmerman maakt een kast op maat.", ["O carpinteiro faz um armário à medida"], "op maat = à medida.", ["v-timmerman"]),
    FB("Een timmerman werkt vooral met ___.", ["hout"], "Madeira.", ["v-timmerman"], choices=["hout","water","stroom"], tr="Um carpinteiro trabalha sobretudo com madeira."),
    CO("text","Vakmensen gezocht", "In Nederland is er een groot tekort aan vakmensen. Elektriciens, loodgieters en monteurs hebben het erg druk, vooral door de energietransitie: veel huizen krijgen zonnepanelen en een warmtepomp. Wie een technisch beroep kiest, vindt daarom meestal snel werk. Veel bedrijven bieden zelfs een opleiding aan op de werkvloer.",
       [("O que falta nos Países Baixos?", ["*Profissionais qualificados (técnicos)","Escritórios","Clientes"]),("Porque têm tanto trabalho?", ["*Por causa da transição energética","Por causa do turismo","Por causa da chuva"]),("O que oferecem muitas empresas?", ["*Formação no local de trabalho","Carros de serviço","Casas"])],
       "vakmensen = profissionais qualificados.", ["v-elektricien","v-monteur"]),
    WO("Onde estão as minhas ferramentas?", ["Waar","ligt","mijn","gereedschap?"], "Gereedschap é singular: ligt.", ["v-gereedschap"]),
    LI("De monteur komt morgen tussen acht en twaalf.", ["De monteur komt morgen tussen acht en twaalf"], "O técnico vem amanhã entre as oito e o meio-dia.", "Frase típica de marcação.", ["v-monteur"]),
  ], diff=3, mins=7)

