    AR("uurtarief","o preço por hora","het", "Het tarief → het uurtarief.", ["v-uurtarief"]),
    TR("pt-nl","Tenho três clientes fixos.", ["Ik heb drie vaste opdrachtgevers","Ik heb drie vaste klanten"], "vast = fixo.", ["v-opdrachtgever"]),
    TR("pt-nl","Desde o ano passado sou independente.", ["Sinds vorig jaar ben ik zzp'er","Ik ben sinds vorig jaar zzp'er","Sinds vorig jaar ben ik zelfstandige"], "sinds + presente.", ["v-zzper"]),
